1	// This file implements lossless archiving of one organization's audit
2	// export. AuditExport hands back detached in-memory records and the caller
3	// separately retains the checkpoint pinning them; an archive serializes the
4	// export so it can be saved to a file when the service instance ends and
5	// read back later, still paired with the caller's own checkpoint and still
6	// usable as the material for RecheckDecisionOffline.
7	//
8	// The format is a length-delimited binary encoding built by hand rather
9	// than encoding/json: JSON text cannot carry bytes that are not valid
10	// UTF-8 without silently replacing them with U+FFFD, which would collapse
11	// genuinely different content (a lone 0xFF, a lone 0xFE and a real U+FFFD)
12	// onto identical records and change their fingerprints. Every string is
13	// written from its exact bytes with a length prefix, and nil slices,
14	// non-nil empty slices and absent payloads are each marked explicitly.
15	//
16	// Integrity never comes from trust in the file. A decode reconstructs the
17	// records and then runs the same whole-material VerifyAudit chain check
18	// against the checkpoint the caller supplies independently; the checkpoint
19	// embedded in the archive is informational only and never authoritative.
20	package darksafe
21	
22	import (
23		"bytes"
24		"crypto/sha256"
25		"encoding/binary"
26		"errors"
27		"fmt"
28	)
29	
30	// ErrInvalidArchive means archive bytes are not a recognizable, complete,
31	// untampered audit archive: a foreign/truncated/trailing-byte framing, a
32	// failed checksum, or content that does not decode. Content-level failures
33	// (missing or mismatched organization, missing, out-of-order or modified
34	// records, a mismatched checkpoint) keep using ErrMissingOrganization and
35	// ErrInvalidRange exactly as the other audit entry points do.
36	var ErrInvalidArchive = errors.New("darksafe: invalid audit archive")
37	
38	// Archive framing:
39	//
40	//	magic   = archiveMagic
41	//	u32 BE  = byte length of the payload that follows
42	//	payload = archivePayloadLen bytes
43	//	32 bytes = SHA-256 checksum of payload
44	//
45	// A second archive concatenated to a first is trailing material, not a
46	// second frame: a read consumes exactly one frame and rejects any byte
47	// beyond it.
48	const archiveMagic = "darksafe-audit-archive-v1\n"
49	
50	const (
51		archiveTagBoolFalse byte = 0
52		archiveTagBoolTrue  byte = 1
53		archiveTagNil       byte = 0
54		archiveTagPresent   byte = 1
55	)
56	
57	// archiveWriter appends length-delimited fields to a byte buffer.
58	type archiveWriter struct {
59		buf []byte
60		err error
61	}
62	
63	func (w *archiveWriter) raw(data []byte) {
64		w.buf = append(w.buf, data...)
65	}
66	
67	// u32 writes a non-negative int as a big-endian uint32.
68	func (w *archiveWriter) u32(v int) {
69		if v < 0 || uint64(v) > 0xffffffff {
70			w.err = fmt.Errorf("%w: length out of range: %d", ErrInvalidArchive, v)
71			return
72		}
73		var b [4]byte
74		binary.BigEndian.PutUint32(b[:], uint32(v))
75		w.buf = append(w.buf, b[:]...)
76	}
77	
78	func (w *archiveWriter) boolean(v bool) {
79		if v {
80			w.buf = append(w.buf, archiveTagBoolTrue)
81		} else {
82			w.buf = append(w.buf, archiveTagBoolFalse)
83		}
84	}
85	
86	// stringField writes a string from its exact memory bytes. Nothing is
87	// validated, replaced or normalized: a lone 0xFF reaches the output as
88	// itself and stays distinguishable from 0xFE and a genuine U+FFFD.
89	func (w *archiveWriter) stringField(s string) {
90		w.u32(len(s))
91		if w.err != nil {
92			return
93		}
94		w.buf = append(w.buf, s...)
95	}
96	
97	// stringList preserves the slice shape explicitly: nil is one marker, a
98	// non-nil list is a marker, a count and the raw strings.
99	func (w *archiveWriter) stringList(items []string) {
100		if items == nil {
101			w.buf = append(w.buf, archiveTagNil)
102			return
103		}
104		w.buf = append(w.buf, archiveTagPresent)
105		w.u32(len(items))
106		for _, s := range items {
107			w.stringField(s)
108		}
109	}
110	
111	// policy writes one Policy by walking the single policy field table, so the
112	// archive's field order is the fingerprint's order by construction. Even the
113	// fingerprint-optional ResourceID is always written here (empty included),
114	// so every field round trips on its own; its placement is fixed by the
115	// table and therefore cannot move a fingerprint boundary.
116	func (w *archiveWriter) policy(p Policy) {
117		for i := range policyFields {
118			f := &policyFields[i]
119			switch f.kind {
120			case policyFieldString, policyFieldOptionalString:
121				w.stringField(f.getString(p))
122			case policyFieldBool:
123				w.boolean(f.getBool(p))
124			}
125		}
126	}
127	
128	func (w *archiveWriter) policyList(policies []Policy) {
129		if policies == nil {
130			w.buf = append(w.buf, archiveTagNil)
131			return
132		}
133		w.buf = append(w.buf, archiveTagPresent)
134		w.u32(len(policies))
135		for _, p := range policies {
136			w.policy(p)
137		}
138	}
139	
140	// change writes the policy-change payload, or a single absence marker:
141	// VerifyAudit only ever accepts a change payload on a policy-change record
142	// and its absence otherwise, but the distinction is encoded explicitly so
143	// decode never has to reconstruct a shape.
144	func (w *archiveWriter) change(c *PolicyChange) {
145		if c == nil {
146			w.buf = append(w.buf, archiveTagNil)
147			return
148		}
149		w.buf = append(w.buf, archiveTagPresent)
150		w.u32(c.Version)
151		w.policyList(c.Policies)
152		w.u32(c.SourceVersion)
153		w.boolean(c.RolledBack)
154	}
155	
156	// decisionRecord writes the decision payload, or a single absence marker:
157	// VerifyAudit only ever accepts a decision payload on a decision record and
158	// its absence otherwise, but the distinction is encoded explicitly so decode
159	// never has to reconstruct a shape. A present payload walks the single
160	// decision field table, so the archive's field order is the fingerprint's
161	// order by construction and every request and decision field round trips.
162	func (w *archiveWriter) decisionRecord(d *DecisionRecord) {
163		if d == nil {
164			w.buf = append(w.buf, archiveTagNil)
165			return
166		}
167		w.buf = append(w.buf, archiveTagPresent)
168		for i := range decisionFields {
169			f := &decisionFields[i]
170			switch f.kind {
171			case decisionFieldString:
172				w.stringField(f.getString(d))
173			case decisionFieldStringList:
174				w.stringList(f.getList(d))
175			case decisionFieldBool:
176				w.boolean(f.getBool(d))
177			case decisionFieldInt:
178				w.u32(f.getInt(d))
179			}
180		}
181	}
182	
183	// EncodeAuditArchive serializes one complete audit export into savable
184	// bytes. org is the organization name, records is its complete chain from
185	// sequence 1 (a valid prefix ending at some historical sequence is enough,
186	// provided cp pins exactly that sequence), and cp is the checkpoint the
187	// caller separately retains. An organization with no records archives too:
188	// records is empty and cp is its sequence-0 genesis checkpoint.
189	//
190	// The whole material is validated exactly as VerifyAudit would before any
191	// bytes are returned: a missing organization is ErrMissingOrganization, and
192	// a missing, out-of-order or foreign record, modified content or checkpoint
193	// mismatch is ErrInvalidRange. On failure no archive bytes are returned.
194	// The checkpoint is carried in the archive for reference, but never stands
195	// in for the separately retained evidence: DecodeAuditArchive always
196	// validates against the checkpoint handed to it. The call is read-only:
197	// neither the records nor any service state are mutated and no audit record
198	// is appended.
199	func EncodeAuditArchive(org string, records []AuditRecord, cp Checkpoint) ([]byte, error) {
200		if org == "" {
201			return nil, ErrMissingOrganization
202		}
203		if err := VerifyAudit(org, records, cp); err != nil {
204			return nil, err
205		}
206	
207		pw := &archiveWriter{}
208		pw.stringField(org)
209		pw.u32(cp.EndSeq)
210		pw.stringField(cp.Fingerprint)
211		pw.u32(len(records))
212		for i := range records {
213			r := &records[i]
214			pw.stringField(r.Org)
215			pw.u32(r.Seq)
216			pw.stringField(r.Kind)
217			pw.change(r.Change)
218			pw.decisionRecord(r.Decision)
219			pw.stringField(r.PrevFingerprint)
220			pw.stringField(r.Fingerprint)
221		}
222		if pw.err != nil {
223			return nil, pw.err
224		}
225		payload := pw.buf
226	
227		out := make([]byte, 0, len(archiveMagic)+4+len(payload)+sha256.Size)
228		out = append(out, archiveMagic...)
229		var lenBuf [4]byte
230		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(payload)))
231		out = append(out, lenBuf[:]...)
232		out = append(out, payload...)
233		sum := sha256.Sum256(payload)
234		out = append(out, sum[:]...)
235		return out, nil
236	}
237	
238	// archiveReader walks one payload without copying string contents: string
239	// fields are backed by the payload slice itself, which is owned by the
240	// decoder and never returned, so callers cannot mutate the input through
241	// the result.
242	type archiveReader struct {
243		data []byte
244		pos  int
245		err  error
246	}
247	
248	func (r *archiveReader) need(n int) bool {
249		if r.err != nil {
250			return false
251		}
252		if n < 0 || r.pos > len(r.data)-n {
253			r.err = fmt.Errorf("%w: truncated archive payload", ErrInvalidArchive)
254			return false
255		}
256		return true
257	}
258	
259	func (r *archiveReader) marker() byte {
260		if !r.need(1) {
261			return 0
262		}
263		b := r.data[r.pos]
264		r.pos++
265		return b
266	}
267	
268	func (r *archiveReader) u32() int {
269		if !r.need(4) {
270			return 0
271		}
272		v := int(binary.BigEndian.Uint32(r.data[r.pos : r.pos+4]))
273		r.pos += 4
274		return v
275	}
276	
277	// boundedCount reads a count and proves at least minBytesPerItem bytes
278	// remain per item, so a hostile payload cannot drive a huge allocation
279	// with a count its body could never satisfy.
280	func (r *archiveReader) boundedCount(minBytesPerItem int) int {
281		n := r.u32()
282		if r.err != nil {
283			return 0
284		}
285		if n < 0 || uint64(n)*uint64(minBytesPerItem) > uint64(len(r.data)-r.pos) {
286			r.err = fmt.Errorf("%w: implausible list count %d", ErrInvalidArchive, n)
287			return 0
288		}
289		return n
290	}
291	
292	func (r *archiveReader) boolean() bool {
293		switch r.marker() {
294		case archiveTagBoolTrue:
295			return true
296		case archiveTagBoolFalse:
297			return false
298		default:
299			if r.err == nil {
300				r.err = fmt.Errorf("%w: invalid boolean marker", ErrInvalidArchive)
301			}
302			return false
303		}
304	}
305	
306	func (r *archiveReader) stringField() string {
307		n := r.u32()
308		if r.err != nil {
309			return ""
310		}
311		if !r.need(n) {
312			return ""
313		}
314		// Conversion copies the bytes, so the result never aliases the input.
315		s := string(r.data[r.pos : r.pos+n])
316		r.pos += n
317		return s
318	}
319	
320	func (r *archiveReader) stringList() []string {
321		switch r.marker() {
322		case archiveTagNil:
323			return nil
324		case archiveTagPresent:
325		default:
326			if r.err == nil {
327				r.err = fmt.Errorf("%w: invalid list marker", ErrInvalidArchive)
328			}
329			return nil
330		}
331		n := r.boundedCount(4) // each item carries at least one length word
332		if r.err != nil {
333			return nil
334		}
335		items := make([]string, n)
336		for i := range items {
337			items[i] = r.stringField()
338		}
339		return items
340	}
341	
342	func (r *archiveReader) policy() Policy {
343		// Read fields in the single table's (write and fingerprint) order. The
344		// fingerprint-optional ResourceID is still a mandatory, fixed field on
345		// the archive, so it is read for every policy including the empty one.
346		var p Policy
347		for i := range policyFields {
348			f := &policyFields[i]
349			switch f.kind {
350			case policyFieldString, policyFieldOptionalString:
351				f.setString(&p, r.stringField())
352			case policyFieldBool:
353				f.setBool(&p, r.boolean())
354			}
355		}
356		return p
357	}
358	
359	func (r *archiveReader) policyList() []Policy {
360		switch r.marker() {
361		case archiveTagNil:
362			return nil
363		case archiveTagPresent:
364		default:
365			if r.err == nil {
366				r.err = fmt.Errorf("%w: invalid policy list marker", ErrInvalidArchive)
367			}
368			return nil
369		}
370		// A policy writes six length words (five strings plus ResourceID) and
371		// one bool byte at minimum.
372		n := r.boundedCount(6*4 + 1)
373		if r.err != nil {
374			return nil
375		}
376		policies := make([]Policy, n)
377		for i := range policies {
378			policies[i] = r.policy()
379		}
380		return policies
381	}
382	
383	func (r *archiveReader) change() *PolicyChange {
384		switch r.marker() {
385		case archiveTagNil:
386			return nil
387		case archiveTagPresent:
388		default:
389			if r.err == nil {
390				r.err = fmt.Errorf("%w: invalid change payload marker", ErrInvalidArchive)
391			}
392			return nil
393		}
394		c := &PolicyChange{}
395		c.Version = r.u32()
396		c.Policies = r.policyList()
397		c.SourceVersion = r.u32()
398		c.RolledBack = r.boolean()
399		return c
400	}
401	
402	func (r *archiveReader) decisionRecord() *DecisionRecord {
403		switch r.marker() {
404		case archiveTagNil:
405			return nil
406		case archiveTagPresent:
407		default:
408			if r.err == nil {
409				r.err = fmt.Errorf("%w: invalid decision payload marker", ErrInvalidArchive)
410			}
411			return nil
412		}
413		// Read fields in the single table's (write and fingerprint) order, so a
414		// field can never be restored into the wrong member or skipped.
415		d := &DecisionRecord{}
416		for i := range decisionFields {
417			f := &decisionFields[i]
418			switch f.kind {
419			case decisionFieldString:
420				f.setString(d, r.stringField())
421			case decisionFieldStringList:
422				f.setList(d, r.stringList())
423			case decisionFieldBool:
424				f.setBool(d, r.boolean())
425			case decisionFieldInt:
426				f.setInt(d, r.u32())
427			}
428		}
429		return d
430	}
431	
432	// DecodeAuditArchive reads one archive produced by EncodeAuditArchive and
433	// returns records that can be handed directly to RecheckDecisionOffline.
434	// org is the organization the caller expects, and cp is the checkpoint the
435	// caller independently retained; the checkpoint embedded in the file is
436	// never treated as evidence, so even an archive carrying a plausible
437	// checkpoint only validates against the one supplied here.
438	//
439	// A missing organization is ErrMissingOrganization. Unrecognized framing,
440	// truncation, a trailing second archive or any other extra byte, a bad
441	// checksum, and undecodable content are ErrInvalidArchive. Records that
442	// decode but are missing, out of order, foreign to the organization,
443	// modified (including a record after the one the caller intends to review)
444	// or mismatched with the supplied checkpoint fail the whole read with
445	// ErrInvalidRange. Failure returns no records. A successful read only
446	// proves the material matches the checkpoint: an original decision that
447	// disagrees with a recomputed one is reported later by offline review, not
448	// treated as archive damage. The result is detached from archive (mutating
449	// one never reaches the other), and the call is read-only.
450	func DecodeAuditArchive(archive []byte, org string, cp Checkpoint) ([]AuditRecord, error) {
451		if org == "" {
452			return nil, ErrMissingOrganization
453		}
454		magicLen := len(archiveMagic)
455		if len(archive) < magicLen+4+sha256.Size || string(archive[:magicLen]) != archiveMagic {
456			return nil, fmt.Errorf("%w: unrecognized audit archive", ErrInvalidArchive)
457		}
458		pos := magicLen
459		payloadLen := int(binary.BigEndian.Uint32(archive[pos : pos+4]))
460		pos += 4
461		checksumEnd := pos + payloadLen
462		if payloadLen < 0 || checksumEnd+sha256.Size != len(archive) {
463			// A short frame is truncation; bytes beyond the one frame (a
464			// concatenated second archive, junk appended to a good file) are a
465			// framing failure too.
466			return nil, fmt.Errorf("%w: truncated or trailing audit archive bytes", ErrInvalidArchive)
467		}
468		payload := archive[pos:checksumEnd]
469		sum := sha256.Sum256(payload)
470		if !bytes.Equal(sum[:], archive[checksumEnd:checksumEnd+sha256.Size]) {
471			return nil, fmt.Errorf("%w: checksum mismatch", ErrInvalidArchive)
472		}
473	
474		r := &archiveReader{data: payload}
475		embeddedOrg := r.stringField()
476		embeddedEndSeq := r.u32()
477		embeddedFingerprint := r.stringField()
478		// Every record writes two payload markers, a sequence word, two
479		// fingerprint length words and org/kind length words: 22 bytes even
480		// when every string is empty.
481		n := r.boundedCount(22)
482		if r.err != nil {
483			return nil, r.err
484		}
485		records := make([]AuditRecord, 0, n)
486		for i := 0; i < n; i++ {
487			var rec AuditRecord
488			rec.Org = r.stringField()
489			rec.Seq = r.u32()
490			rec.Kind = r.stringField()
491			rec.Change = r.change()
492			rec.Decision = r.decisionRecord()
493			rec.PrevFingerprint = r.stringField()
494			rec.Fingerprint = r.stringField()
495			records = append(records, rec)
496		}
497		if r.err != nil {
498			return nil, r.err
499		}
500		if r.pos != len(payload) {
501			return nil, fmt.Errorf("%w: %d unconsumed archive bytes", ErrInvalidArchive, len(payload)-r.pos)
502		}
503	
504		// Content checks reuse the exact audit-range validation the live export
505		// and offline review paths use, so an archive can never smuggle in a
506		// shape those entry points would reject.
507		if embeddedOrg != org {
508			return nil, fmt.Errorf("%w: archive organization %q does not match %q", ErrInvalidRange, embeddedOrg, org)
509		}
510		// The embedded checkpoint is informational; still, contradicting its own
511		// header means the payload was altered, and the authoritative check
512		// below always uses the caller's independently retained checkpoint.
513		if embeddedEndSeq != cp.EndSeq || embeddedFingerprint != cp.Fingerprint {
514			return nil, fmt.Errorf("%w: embedded checkpoint does not match the retained checkpoint", ErrInvalidRange)
515		}
516		if err := VerifyAudit(org, records, cp); err != nil {
517			return nil, err
518		}
519		return records, nil
520	}
521

