30		for i, p := range paths {
31			fv := decisionFieldByPath(&d, p)
32			switch fv.Kind() {
33			case reflect.String:
34				v := fmt.Sprintf("\x00decision-field-%d\x00", i)
35				fv.SetString(v)
36				stringSentinel[p] = v
37			case reflect.Bool:
38				fv.SetBool(true)
39				boolPaths[p] = true
40			case reflect.Int:
41				fv.SetInt(int64(1000 + i))
42				intSentinel[p] = 1000 + i
43			case reflect.Slice:
44				v := fmt.Sprintf("\x00decision-list-%d\x00", i)
45				fv.Set(reflect.ValueOf([]string{v}))
46				listSentinel[p] = v
47			}
48		}
49	
50		// The fingerprint's group markers belong to exactly these fields; moving
51		// one would change every decision fingerprint.
52		wantGroupTag := map[string]fingerprintTag{
53			"Request.Subject.ID":  tagSubject,
54			"Request.Resource.ID": tagResource,
55			"Decision.Allowed":    tagDecision,
56		}
57	
58		seen := make(map[string]bool)
59		var orderedPaths []string
60		for i := range decisionFields {
61			f := &decisionFields[i]
62			var path string
63			switch f.kind {
64			case decisionFieldString:
65				got := f.getString(&d)
66				path = matchStringSentinel(got, stringSentinel)
67				if path == "" {
68					t.Fatalf("field table entry %d reads %q, not any distinct string field", i, got)
69				}
70			case decisionFieldStringList:
71				got := f.getList(&d)
72				if len(got) != 1 {
73					t.Fatalf("field table entry %d reads %v, not any stamped list field", i, got)
74				}
75				path = matchStringSentinel(got[0], listSentinel)
