189	// decisionLeafPaths lists every leaf field path of DecisionRecord in
190	// declaration order, discovered by reflection so a new struct field fails
191	// the test instead of silently escaping the table.
192	func decisionLeafPaths(t *testing.T) []string {
193		t.Helper()
194		var paths []string
195		var walk func(tp reflect.Type, prefix string)
196		walk = func(tp reflect.Type, prefix string) {
197			for i := 0; i < tp.NumField(); i++ {
198				sf := tp.Field(i)
199				p := prefix + sf.Name
200				switch sf.Type.Kind() {
201				case reflect.Struct:
202					walk(sf.Type, p+".")
203				case reflect.String, reflect.Bool, reflect.Int:
204					paths = append(paths, p)
205				case reflect.Slice:
206					if sf.Type.Elem().Kind() != reflect.String {
207						t.Fatalf("DecisionRecord.%s has unhandled slice type %v; extend decisionFields", p, sf.Type)
208					}
209					paths = append(paths, p)
210				default:
211					t.Fatalf("DecisionRecord.%s has unhandled kind %v; extend decisionFields", p, sf.Type.Kind())
212				}
213			}
214		}
215		walk(reflect.TypeOf(DecisionRecord{}), "")
216		return paths
217	}
218	
219	// decisionFieldByPath resolves a dot-separated leaf path to its settable
220	// value inside d.
221	func decisionFieldByPath(d *DecisionRecord, path string) reflect.Value {
222		v := reflect.ValueOf(d).Elem()
223		for _, part := range strings.Split(path, ".") {
224			v = v.FieldByName(part)
225		}
226		return v
227	}
228	
229	// matchStringSentinel returns the field path whose sentinel equals got.
230	func matchStringSentinel(got string, sentinels map[string]string) string {
231		for p, v := range sentinels {
232			if got == v {
233				return p
234			}
235		}
236		return ""
237	}
