239	// matchBoolSentinel identifies the unique bool field whose value the spec
240	// reads; every bool field is stamped true, so clearing the read field (and
241	// only it) flips the getter to false.
242	func matchBoolSentinel(f *decisionFieldSpec, d *DecisionRecord, boolPaths map[string]bool) string {
243		for p := range boolPaths {
244			probe := *d
245			decisionFieldByPath(&probe, p).SetBool(false)
246			if !f.getBool(&probe) {
247				return p
248			}
249		}
