1	// Regression coverage for rolling an organization's policy set back to a
2	// historically published EMPTY version. An empty set is a genuine historical
3	// version, not a missing one: rolling back to it must revoke a current allow,
4	// consume exactly one consecutive new version (the rollback returns the new
5	// version number, never the target's), and leave a rollback-marked
6	// policy-change record carrying the empty content. The resulting default
7	// denial must survive online recheck and offline review from both the live
8	// export and a decoded archive, with the other (allowing) versions never
9	// substituted. Owner or scope roles on the subject must not change the
10	// organization decision.
11	//
12	// Both empty shapes published in the wild are covered: a nil policy slice and
13	// an explicit non-nil empty slice. The two are authorization-equivalent, and
14	// every public surface must accept either as a valid rollback target.
15	package darksafe
16	
17	import (
18		"errors"
19		"reflect"
20		"testing"
21	)
22	
23	// emptyRollbackShapes are the two ways "no policies" reaches Publish.
24	func emptyRollbackShapes() map[string][]Policy {
25		return map[string][]Policy{
26			"nil slice":      nil,
27			"empty slice":    {},
28			"empty make":     make([]Policy, 0),
29			"empty with cap": make([]Policy, 0, 4),
30		}
31	}
32	
33	// emptyRollbackAllowSet is the current allow policy the rollback revokes.
34	func emptyRollbackAllowSet() []Policy {
35		return []Policy{allowPolicy("p-ledger-read", "u1", "read", "org/acme/ledger", false)}
36	}
37	
38	// emptyRollbackRequest is a fully populated, organization-consistent request
39	// for an enabled subject; the allow set above grants it before the rollback.
40	func emptyRollbackRequest(org string) OrgRequest {
41		return request(org, "u1", "ledger-1", "org/acme/ledger", "read")
42	}
43	
44	// buildEmptyRollbackStore publishes the empty set as v1, the allow set as v2,
45	// and records one allowed decision under v2. It leaves the organization at
46	// current version 2 with three audit records (publish, publish, decision).
47	func buildEmptyRollbackStore(t *testing.T, org string, emptyPolicies []Policy) (*Store, OrgRequest, Decision) {
48		t.Helper()
49		s := NewStore()
50		if v, err := s.Publish(org, 0, emptyPolicies); err != nil || v != 1 {
51			t.Fatalf("publish empty v1 = %d, %v; want 1, nil", v, err)
52		}
53		allow := emptyRollbackAllowSet()
54		if v, err := s.Publish(org, 1, allow); err != nil || v != 2 {
55			t.Fatalf("publish allow v2 = %d, %v; want 2, nil", v, err)
56		}
57		req := emptyRollbackRequest(org)
58		before := s.Decide(org, req)
59		wantBefore := Decision{
60			Allowed: true, Reason: "matched allow policy",
61			Matched: []string{"p-ledger-read"}, Version: 2,
62		}
63		if !reflect.DeepEqual(before, wantBefore) {
64			t.Fatalf("decision under v2 = %+v, want %+v", before, wantBefore)
65		}
66		return s, req, before
67	}
68	
69	// TestRollbackToEmptyVersionRevokesAuthorization is the end-to-end contract:
70	// rollback to the empty historical version revokes the current grant, the
71	// version advances exactly once, and the new version's full policy set is the
72	// empty collection.
73	func TestRollbackToEmptyVersionRevokesAuthorization(t *testing.T) {
74		for shape, emptyPolicies := range emptyRollbackShapes() {
75			t.Run(shape, func(t *testing.T) {
76				org := "acme-" + shape
77				s, req, before := buildEmptyRollbackStore(t, org, emptyPolicies)
78				allow := emptyRollbackAllowSet()
79	
80				// The rollback targets the real historical v1 and must return the
81				// NEW consecutive version, not the target version number.
82				newVersion, err := s.Rollback(org, 2, 1)
83				if err != nil || newVersion != 3 {
84					t.Fatalf("rollback to empty v1 = %d, %v; want new version 3, nil", newVersion, err)
85				}
86				if got := s.CurrentVersion(org); got != 3 {
87					t.Fatalf("current version = %d, want 3 after rollback", got)
88				}
89	
90				// The new version exists and queries successfully as an empty
91				// collection; history is intact underneath it.
92				gotV3, err := s.Policies(org, 3)
93				if err != nil {
94					t.Fatalf("Policies(v3): %v", err)
95				}
96				if len(gotV3) != 0 {
97					t.Fatalf("Policies(v3) = %+v, want empty collection", gotV3)
98				}
99				gotV1, err := s.Policies(org, 1)
100				if err != nil || len(gotV1) != 0 {
101					t.Fatalf("Policies(v1) = %+v, %v; want empty, nil", gotV1, err)
102				}
103				gotV2, err := s.Policies(org, 2)
104				if err != nil || !reflect.DeepEqual(gotV2, allow) {
105					t.Fatalf("Policies(v2) = %+v, %v; want the original allow set", gotV2, err)
106				}
107	
108				// The same admissible request is now default-denied under the new
109				// version, with the no-matching-allow reason and an empty hit list.
110				wantDenial := Decision{
111					Allowed: false, Reason: "no matching allow policy",
112					Matched: []string{}, Version: 3,
113				}
114				d := s.Decide(org, req)
115				if !reflect.DeepEqual(d, wantDenial) {
116					t.Fatalf("post-rollback decision = %+v, want %+v", d, wantDenial)
117				}
118	
119				// Owner and formerly-sufficient scope roles never substitute for
120				// an organization policy: the empty set denies regardless.
121				roleReq := req
122				roleReq.Subject.Roles = []string{"owner", "org/acme/ledger:read"}
123				if dRole := s.Decide(org, roleReq); !reflect.DeepEqual(dRole, wantDenial) {
124					t.Fatalf("decision with owner/scoped roles = %+v, want %+v", dRole, wantDenial)
125				}
126	
127				// Historical review is pinned per version and was not rewritten:
128				// v1 denies empty, v2 still allows exactly as recorded before.
129				if d1 := s.Review(org, 1, req); d1.Allowed || d1.Version != 1 ||
130					d1.Reason != "no matching allow policy" {
131					t.Fatalf("review v1 = %+v, want default denial at v1", d1)
132				}
133				if d2 := s.Review(org, 2, req); !reflect.DeepEqual(d2, before) {
134					t.Fatalf("review v2 = %+v, want preserved %+v", d2, before)
135				}
136	
137				// Audit chain: publish v1 (seq 1), publish v2 (seq 2), the allowed
138				// decision (seq 3), rollback (seq 4), denial decision (seq 5), and
139				// the owner-role denial decision (seq 6).
140				recs, cp, err := s.AuditExport(org, 0)
141				if err != nil {
142					t.Fatalf("AuditExport: %v", err)
143				}
144				if len(recs) != 6 {
145					t.Fatalf("audit records = %d, want 6", len(recs))
146				}
147				if err := VerifyAudit(org, recs, cp); err != nil {
148					t.Fatalf("VerifyAudit after empty rollback: %v", err)
149				}
150				for i, r := range recs {
151					if r.Seq != i+1 || r.Org != org {
152						t.Fatalf("record %d has unexpected seq/org: %+v", i+1, r)
153					}
154				}
155				// Earlier records keep their original content and order.
156				if recs[0].Kind != AuditPolicyChange || recs[0].Change.Version != 1 ||
157					len(recs[0].Change.Policies) != 0 || recs[0].Change.RolledBack {
158					t.Fatalf("v1 change record altered: %+v", recs[0].Change)
159				}
160				if recs[1].Kind != AuditPolicyChange ||
161					!reflect.DeepEqual(recs[1].Change.Policies, allow) ||
162					recs[1].Change.RolledBack || recs[1].Change.SourceVersion != 0 {
163					t.Fatalf("v2 change record altered: %+v", recs[1].Change)
164				}
165				if recs[2].Kind != AuditDecision ||
166					!reflect.DeepEqual(recs[2].Decision.Decision, before) ||
167					!reflect.DeepEqual(recs[2].Decision.Request, req) {
168					t.Fatalf("pre-rollback decision record altered: %+v", recs[2].Decision)
169				}
170				// The rollback record names the new version, the empty content,
171				// and explicitly identifies itself as a rollback from v1.
172				chg := recs[3].Change
173				if recs[3].Kind != AuditPolicyChange || chg == nil {
174					t.Fatalf("record 4 is not a policy change: %+v", recs[3])
175				}
176				if chg.Version != 3 {
177					t.Fatalf("rollback record version = %d, want new version 3", chg.Version)
178				}
179				if len(chg.Policies) != 0 {
180					t.Fatalf("rollback record policies = %+v, want empty", chg.Policies)
181				}
182				if !chg.RolledBack || chg.SourceVersion != 1 {
183					t.Fatalf("rollback record must be tagged RolledBack with source v1: %+v", chg)
184				}
185				// The denial record stores the request and the exact result.
186				dr := recs[4].Decision
187				if recs[4].Kind != AuditDecision || dr == nil {
188					t.Fatalf("record 5 is not a decision: %+v", recs[4])
189				}
190				if !reflect.DeepEqual(dr.Decision, wantDenial) {
191					t.Fatalf("stored denial = %+v, want %+v", dr.Decision, wantDenial)
192				}
193				if !reflect.DeepEqual(dr.Request, req) {
194					t.Fatalf("stored request = %+v, want %+v", dr.Request, req)
195				}
196	
197				// The owner-role denial is seq 6 and reproduces the same result.
198				rcOwner, err := s.RecheckDecision(org, 6)
199				if err != nil {
200					t.Fatalf("RecheckDecision(6): %v", err)
201				}
202				if !reflect.DeepEqual(rcOwner, wantDenial) {
203					t.Fatalf("owner-role recheck = %+v, want %+v", rcOwner, wantDenial)
204				}
205				// The earlier allowed decision rechecks unchanged as well.
206				rcBefore, err := s.RecheckDecision(org, 3)
207				if err != nil || !reflect.DeepEqual(rcBefore, before) {
208					t.Fatalf("RecheckDecision(3) = %+v, %v; want %+v", rcBefore, err, before)
209				}
210	
211				// Offline review from the complete export plus the separately
212				// retained checkpoint must find the empty v3 content in the
213				// rollback record before the decision; it must not report the
214				// version missing and must not fall back to allowing v2.
215				review, err := RecheckDecisionOffline(org, recs, cp, 5)
216				if err != nil {
217					t.Fatalf("RecheckDecisionOffline after empty rollback: %v", err)
218				}
219				if !reflect.DeepEqual(review.Original, wantDenial) ||
220					!reflect.DeepEqual(review.Recomputed, wantDenial) || !review.Consistent {
221					t.Fatalf("offline review = %+v, want both decisions %+v and consistent", review, wantDenial)
222				}
223	
224				// The same offline review must work through an archived export:
225				// encode, decode against the retained checkpoint, then review.
226				archive, err := EncodeAuditArchive(org, recs, cp)
227				if err != nil {
228					t.Fatalf("EncodeAuditArchive: %v", err)
229				}
230				decoded, err := DecodeAuditArchive(archive, org, cp)
231				if err != nil {
232					t.Fatalf("DecodeAuditArchive: %v", err)
233				}
234				arcReview, err := RecheckDecisionOffline(org, decoded, cp, 5)
235				if err != nil {
236					t.Fatalf("offline review from archive: %v", err)
237				}
238				if !arcReview.Consistent || !reflect.DeepEqual(arcReview.Recomputed, wantDenial) {
239					t.Fatalf("archived offline review = %+v, want consistent %+v", arcReview, wantDenial)
240				}
241	
242				// A later re-publish of an allow set must not change the recorded
243				// denial's offline review: v3 stays the version actually used.
244				if v, err := s.Publish(org, 3, allow); err != nil || v != 4 {
245					t.Fatalf("publish v4 = %d, %v; want 4, nil", v, err)
246				}
247				fullRecs, fullCP, err := s.AuditExport(org, 0)
248				if err != nil || len(fullRecs) != 7 {
249					t.Fatalf("export after v4 = %d records, %v", len(fullRecs), err)
250				}
251				if err := VerifyAudit(org, fullRecs, fullCP); err != nil {
252					t.Fatalf("chain with v4 does not verify: %v", err)
253				}
254				later, err := RecheckDecisionOffline(org, fullRecs, fullCP, 5)
255				if err != nil {
256					t.Fatalf("offline review with later v4: %v", err)
257				}
258				if !later.Consistent || !reflect.DeepEqual(later.Recomputed, wantDenial) {
259					t.Fatalf("review with later allowing v4 = %+v, want unchanged %+v", later, wantDenial)
260				}
261				if d := s.Decide(org, req); d.Version != 4 || !d.Allowed {
262					t.Fatalf("live decision under v4 = %+v, want allowed at v4", d)
263				}
264			})
265		}
266	}
267	
268	// TestRollbackToEmptyVersionFailuresLeaveStateUntouched preserves the existing
269	// failure contract for an empty target: a missing historical version is
270	// ErrVersionNotFound, a stale expected current version is ErrVersionConflict
271	// (the empty target is not exempt from the expected-version check), and no
272	// failure moves the current version, changes policy content, or appends an
273	// audit record.
274	func TestRollbackToEmptyVersionFailuresLeaveStateUntouched(t *testing.T) {
275		for shape, emptyPolicies := range emptyRollbackShapes() {
276			t.Run(shape, func(t *testing.T) {
277				org := "acme-fail-" + shape
278				s, req, _ := buildEmptyRollbackStore(t, org, emptyPolicies)
279	
280				// Before any rollback: a stale expected version against the empty
281				// target conflicts, and must not consume version 3 or a seq.
282				if _, err := s.Rollback(org, 9, 1); !errors.Is(err, ErrVersionConflict) {
283					t.Fatalf("stale rollback before success err = %v, want ErrVersionConflict", err)
284				}
