289					t.Fatalf("v3 exists after failed rollback, err = %v", err)
290				}
291				preRecs, _, err := s.AuditExport(org, 0)
292				if err != nil || len(preRecs) != 3 {
293					t.Fatalf("records before rollback = %d, %v; want 3", len(preRecs), err)
294				}
295	
296				// The successful rollback then creates v3.
297				if v, err := s.Rollback(org, 2, 1); err != nil || v != 3 {
298					t.Fatalf("rollback = %d, %v; want 3, nil", v, err)
