1	// End-to-end CLI regression for rolling back to an empty historical policy
2	// version and then reviewing the resulting default denial offline with
3	// `darksafe review`. The archive is built from the real Store, written to a
4	// file, and re-read solely through the command using a separately retained
5	// checkpoint, exactly as an operator would after the service instance ended.
6	package main
7	
8	import (
9		"os"
10		"path/filepath"
11		"strings"
12		"testing"
13	
14		"github.com/asdhoaiqqq/darksafe-access/darksafe"
15	)
16	
17	// emptyRollbackFixture builds: publish empty v1, publish allow v2, an allowed
18	// decision (seq 3), rollback to v1 producing v3 (seq 4), and the post-rollback
19	// default-denial decision (seq 5). It covers both empty input shapes.
20	func emptyRollbackFixture(t *testing.T, org string, emptyPolicies []darksafe.Policy) (string, darksafe.Checkpoint) {
21		t.Helper()
22		s := darksafe.NewStore()
23		if v, err := s.Publish(org, 0, emptyPolicies); err != nil || v != 1 {
24			t.Fatalf("publish empty v1: %d %v", v, err)
25		}
