package darksafe

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"testing"
)

// TestCompatDump exercises publish, rollback and decisions over tricky
// content and prints every record fingerprint plus the exact archive bytes
// hash, so the output can be diffed across the refactor.
func TestCompatDump(t *testing.T) {
	orgs := []string{"acme", "中文组织", "raw-\xff-org", "raw-\xfe-org", "real-�-org", "ctrl-\t\n -org"}
	for _, org := range orgs {
		s := NewStore()
		// v1: empty set, nil shape.
		if _, err := s.Publish(org, 0, nil); err != nil {
			t.Fatal(err)
		}
		// v2: mixed content, non-nil empty then full.
		pols := []Policy{
			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true},
			{ID: "p2\xff", Subject: "中文用户", Action: "wr ite", Scope: "org/a/b", Effect: EffectDeny, ResourceID: "res-\xfe"},
			{ID: "p3", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: "real-�"},
			{ID: "p4", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny, ResourceID: "sp ace\tctrl\n"},
		}
		if _, err := s.Publish(org, 1, pols); err != nil {
			t.Fatal(err)
		}
		// v3: non-nil empty set.
		if _, err := s.Publish(org, 2, []Policy{}); err != nil {
			t.Fatal(err)
		}
		// decisions with nil and non-nil-empty role lists.
		req := OrgRequest{
			SubjectOrg: org, ResourceOrg: org,
			Subject:  Subject{ID: "u1", Roles: nil},
			Resource: Resource{ID: "r1", Scope: "org/a"},
			Action:   "read",
		}
		s.Decide(org, req)
		req.Subject.Roles = []string{}
		req.Resource.ID = "res-\xfe"
		s.Decide(org, req)
		// v4: rollback to v2.
		if _, err := s.Rollback(org, 3, 2); err != nil {
			t.Fatal(err)
		}
		// v5: rollback to the empty v3.
		if _, err := s.Rollback(org, 4, 3); err != nil {
			t.Fatal(err)
		}
		s.Decide(org, req)

		recs, cp, err := s.AuditExport(org, 0)
		if err != nil {
			t.Fatal(err)
		}
		fmt.Printf("org=%q records=%d\n", org, len(recs))
		for _, r := range recs {
			fmt.Printf("  seq=%d kind=%s fp=%s prev=%s\n", r.Seq, r.Kind, r.Fingerprint, r.PrevFingerprint)
			if r.Change != nil {
				fmt.Printf("    change v=%d src=%d rb=%v nil=%v len=%d\n",
					r.Change.Version, r.Change.SourceVersion, r.Change.RolledBack,
					r.Change.Policies == nil, len(r.Change.Policies))
			}
		}
		fmt.Printf("  checkpoint end=%d fp=%s\n", cp.EndSeq, cp.Fingerprint)
		archive, err := EncodeAuditArchive(org, recs, cp)
		if err != nil {
			t.Fatal(err)
		}
		sum := sha256.Sum256(archive)
		fmt.Printf("  archive len=%d sha256=%s\n", len(archive), hex.EncodeToString(sum[:]))
		decoded, err := DecodeAuditArchive(archive, org, cp)
		if err != nil {
			t.Fatal(err)
		}
		for i, r := range decoded {
			if r.Fingerprint != recs[i].Fingerprint {
				t.Fatalf("decoded record %d fingerprint drifted", i)
			}
		}
	}
}

